// Measures what a runner gives a node_modules restore: download throughput with parallel range
// requests, and sequential disk writes. Dependency-free.
//
//   node net.ts download --url URL [--connections N[,N...]] [--chunk-mb M] [--out FILE] [--label TEXT]
//     Downloads URL (or the URL in the environment variable that --url-env names) with N
//     concurrent range requests of M MB, once per N, and discards the data unless --out is given.
//   node net.ts disk --file PATH [--mb N]
//     Writes N MB sequentially in 8 MB writes, then flushes them to the device.

import { randomBytes } from 'crypto';
import * as fs from 'fs';

type Args = Map<string, string>;

function parseArgs(argv: readonly string[]): Args {
	const args: Args = new Map();
	for (let i = 0; i < argv.length; i += 2) {
		args.set(argv[i].replace(/^--/, ''), argv[i + 1]);
	}
	return args;
}

function report(result: Record<string, unknown>): void {
	const line = JSON.stringify(result);
	console.log(line);
	if (process.env.GITHUB_STEP_SUMMARY) {
		fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, `- \`${line}\`\n`);
	}
}

async function size(url: string): Promise<number> {
	const response = await fetch(url, { headers: { Range: 'bytes=0-0' } });
	const range = response.headers.get('content-range');
	await response.body?.cancel();
	if (response.status !== 206 || !range) {
		throw new Error(`No range support: HTTP ${response.status}`);
	}
	return Number(range.split('/')[1]);
}

async function fetchRange(url: string, from: number, to: number): Promise<Buffer> {
	for (let attempt = 1; ; attempt++) {
		try {
			const response = await fetch(url, { headers: { Range: `bytes=${from}-${to}` } });
			if (response.status !== 206) {
				throw new Error(`HTTP ${response.status}`);
			}
			return Buffer.from(await response.arrayBuffer());
		} catch (err) {
			if (attempt === 4) {
				throw err;
			}
		}
	}
}

async function download(args: Args): Promise<void> {
	const url = args.get('url') ?? process.env[args.get('url-env') ?? ''];
	if (!url) {
		report({ label: args.get('label'), error: 'no URL' });
		return;
	}
	const chunk = Number(args.get('chunk-mb') ?? '8') * 1024 * 1024;
	const out = args.get('out');
	const total = await size(url);
	for (const connections of (args.get('connections') ?? '8').split(',').map(Number)) {
		const handle = out ? await fs.promises.open(out, 'w') : undefined;
		const chunks = Math.ceil(total / chunk);
		let next = 0;
		const start = performance.now();
		try {
			await Promise.all(Array.from({ length: Math.min(connections, chunks) }, async () => {
				while (next < chunks) {
					const index = next++;
					const from = index * chunk;
					const data = await fetchRange(url, from, Math.min(total, from + chunk) - 1);
					await handle?.write(data, 0, data.length, from);
				}
			}));
		} finally {
			await handle?.close();
		}
		const seconds = (performance.now() - start) / 1000;
		report({ label: args.get('label'), connections, chunkMB: chunk / 1024 / 1024, MB: Math.round(total / 1e6), seconds: Number(seconds.toFixed(2)), MBps: Math.round(total / seconds / 1e6), toDisk: !!out });
	}
}

async function disk(args: Args): Promise<void> {
	const file = args.get('file')!;
	const megabytes = Number(args.get('mb') ?? '4096');
	const buffer = randomBytes(8 * 1024 * 1024);
	const handle = await fs.promises.open(file, 'w');
	const start = performance.now();
	for (let written = 0; written < megabytes; written += 8) {
		await handle.write(buffer, 0, buffer.length);
	}
	const writeSeconds = (performance.now() - start) / 1000;
	await handle.sync();
	const totalSeconds = (performance.now() - start) / 1000;
	await handle.close();
	fs.rmSync(file);
	report({ label: 'disk', file, MB: megabytes, bufferedMBps: Math.round(megabytes / writeSeconds), withFlushMBps: Math.round(megabytes / totalSeconds), writeSeconds: Number(writeSeconds.toFixed(2)), totalSeconds: Number(totalSeconds.toFixed(2)) });
}

const [command, ...rest] = process.argv.slice(2);
const main = command === 'download' ? download : command === 'disk' ? disk : undefined;
if (!main) {
	console.error('Usage: node net.ts download|disk ...');
	process.exit(1);
}
main(parseArgs(rest)).catch(err => {
	console.error(err);
	process.exit(1);
});
